-- =====================================================================
-- NOTALEGIS — Script completo de base de datos
-- Crea TODAS las tablas del sistema (tal como están hoy, con todas las
-- migraciones ya aplicadas) y carga los datos de ejemplo para la
-- presentación (usuarios de prueba, configuración y ~50 registros
-- falsos por cada gestión operativa).
--
-- Cómo usarlo en una computadora nueva:
--   1. Instalar SQL Server Express (instancia por defecto "SQLEXPRESS").
--   2. Abrir este archivo con sqlcmd o SQL Server Management Studio.
--   3. Ejecutarlo completo, de una sola vez.
--   4. Listo — la base "NotalegisDB" queda creada y cargada.
--
-- Ver también: GUIA_MIGRACION_NOTEBOOK.md para los pasos de instalación
-- de SQL Server y ajuste de la cadena de conexión del programa.
-- =====================================================================

IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'NotalegisDB')
BEGIN
    CREATE DATABASE NotalegisDB;
END
GO

USE NotalegisDB;
GO

-- Sin esto, un servidor SQL en español (que interpreta las fechas como día/mes/año)
-- puede rechazar las fechas de este script, que están escritas como año-mes-día.
SET DATEFORMAT ymd;
GO

-- =====================================================================
-- 1. USUARIOS (login del sistema)
-- =====================================================================
CREATE TABLE Usuarios (
    Id             INT IDENTITY(1,1) PRIMARY KEY,
    NombreUsuario  NVARCHAR(50)  NOT NULL,
    Contraseña     NVARCHAR(255) NOT NULL,   -- hash BCrypt, nunca texto plano
    Rol            NVARCHAR(50)  NOT NULL DEFAULT 'escribano', -- Administrador / Escribana Adjunta / Secretaria / Procurador
    IntentosLogin  INT           NOT NULL DEFAULT 0,
    BloqueadoHasta DATETIME      NULL
);
GO

-- =====================================================================
-- 2. CONFIGURACION (parámetros generales de la escribanía)
-- =====================================================================
CREATE TABLE Configuracion (
    Id                INT IDENTITY(1,1) PRIMARY KEY,
    Clave             NVARCHAR(100) NOT NULL,
    Valor             NVARCHAR(MAX) NULL,
    TipoConfiguracion NVARCHAR(50)  NOT NULL,
    Descripcion       NVARCHAR(255) NULL,
    FechaActualizacion DATETIME     NOT NULL DEFAULT GETDATE()
);
GO

-- =====================================================================
-- 3. TIPOESCRITURA (catálogo de tipos de acto notarial)
-- =====================================================================
CREATE TABLE TipoEscritura (
    Id            INT IDENTITY(1,1) PRIMARY KEY,
    Nombre        NVARCHAR(100) NOT NULL,
    Descripcion   NVARCHAR(500) NULL,
    RutaPlantilla NVARCHAR(500) NULL,
    Activo        BIT           NOT NULL DEFAULT 1,
    FechaCreacion DATETIME      NOT NULL DEFAULT GETDATE()
);
GO

-- =====================================================================
-- 4. CLIENTE
-- =====================================================================
CREATE TABLE Cliente (
    Id            INT IDENTITY(1,1) PRIMARY KEY,
    Nombre        NVARCHAR(100) NOT NULL,
    Apellido      NVARCHAR(100) NOT NULL,
    DNI           NVARCHAR(20)  NOT NULL,
    Edad          INT           NULL,
    Telefono      NVARCHAR(50)  NULL,
    Email         NVARCHAR(100) NULL,
    Direccion     NVARCHAR(255) NULL,
    Estado        NVARCHAR(50)  NULL,
    Observaciones VARCHAR(255)  NULL,
    Eliminado     BIT           NOT NULL DEFAULT 0
);
GO

-- =====================================================================
-- 5. ESTADOCLIENTE (historial de cambios de estado — hoy sin uso activo)
-- =====================================================================
CREATE TABLE EstadoCliente (
    Id            INT IDENTITY(1,1) PRIMARY KEY,
    IdCliente     INT           NOT NULL,
    Estado        NVARCHAR(255) NOT NULL,
    FechaRegistro DATETIME      NOT NULL,
    CONSTRAINT FK_EstadoCliente_Cliente FOREIGN KEY (IdCliente) REFERENCES Cliente(Id)
);
GO

-- =====================================================================
-- 6. TURNO
-- =====================================================================
CREATE TABLE Turno (
    Id            INT IDENTITY(1,1) PRIMARY KEY,
    IdCliente     INT           NOT NULL,
    FechaHora     DATETIME      NOT NULL,
    Motivo        NVARCHAR(255) NULL,
    Estado        NVARCHAR(50)  NULL,
    Observaciones NVARCHAR(MAX) NULL,
    Confirmado    BIT           NOT NULL DEFAULT 0,
    TipoTramite   NVARCHAR(100) NULL,
    Eliminado     BIT           NOT NULL DEFAULT 0,
    CONSTRAINT FK_Turno_Cliente FOREIGN KEY (IdCliente) REFERENCES Cliente(Id)
);
GO

-- =====================================================================
-- 7. TRAMITE  (ojo: "Cliente" es texto libre, no clave foránea)
-- =====================================================================
CREATE TABLE tramite (
    Id                    INT IDENTITY(1,1) PRIMARY KEY,
    Cliente               NVARCHAR(100)  NOT NULL,
    TipoTramite           NVARCHAR(100)  NOT NULL,
    FechaInicio           DATE           NOT NULL,
    FechaVencimiento      DATE           NOT NULL,
    Estado                NVARCHAR(50)   NOT NULL,
    Prioridad             NVARCHAR(20)   NOT NULL,
    DocumentacionCompleta BIT            NULL,
    Observaciones         NVARCHAR(MAX)  NULL,
    NumeroExpediente      NVARCHAR(100)  NULL,
    FechaCreacion         DATETIME       NOT NULL DEFAULT GETDATE(),
    MontoEstimado         DECIMAL(18,2)  NULL,
    Eliminado             BIT            NOT NULL DEFAULT 0
);
GO

-- =====================================================================
-- 8. COBROS (presupuestos)
-- =====================================================================
CREATE TABLE Cobros (
    Id                   INT IDENTITY(1,1) PRIMARY KEY,
    ClienteId            INT           NOT NULL,
    NumeroExpediente     NVARCHAR(50)  NOT NULL,
    FechaCobro           DATETIME      NOT NULL DEFAULT GETDATE(),
    TipoTramite          NVARCHAR(100) NULL,

    ImpGananciasPorc     DECIMAL(5,2)  NOT NULL DEFAULT 0,
    ImpGananciasBase     DECIMAL(18,2) NOT NULL DEFAULT 0,
    ImpGananciasImporte  DECIMAL(18,2) NOT NULL DEFAULT 0,

    ITIPorc              DECIMAL(5,2)  NOT NULL DEFAULT 0,
    ITIBase              DECIMAL(18,2) NOT NULL DEFAULT 0,
    ITIImporte           DECIMAL(18,2) NOT NULL DEFAULT 0,

    ImpSellosPorc        DECIMAL(5,2)  NOT NULL DEFAULT 0,
    ImpSellosBase        DECIMAL(18,2) NOT NULL DEFAULT 0,
    ImpSellosImporte     DECIMAL(18,2) NOT NULL DEFAULT 0,

    TasaGeneralPorc      DECIMAL(5,2)  NOT NULL DEFAULT 0,
    TasaGeneralBase      DECIMAL(18,2) NOT NULL DEFAULT 0,
    TasaGeneralImporte   DECIMAL(18,2) NOT NULL DEFAULT 0,

    SelloMatrizPorc      DECIMAL(5,2)  NOT NULL DEFAULT 0,
    SelloMatrizBase      DECIMAL(18,2) NOT NULL DEFAULT 0,
    SelloMatrizImporte   DECIMAL(18,2) NOT NULL DEFAULT 0,

    CertificadosPorc     DECIMAL(5,2)  NOT NULL DEFAULT 0,
    CertificadosBase     DECIMAL(18,2) NOT NULL DEFAULT 0,
    CertificadosImporte  DECIMAL(18,2) NOT NULL DEFAULT 0,

    DiligenciamientoPorc    DECIMAL(5,2)  NOT NULL DEFAULT 0,
    DiligenciamientoBase    DECIMAL(18,2) NOT NULL DEFAULT 0,
    DiligenciamientoImporte DECIMAL(18,2) NOT NULL DEFAULT 0,

    HonorariosPorc       DECIMAL(5,2)  NOT NULL DEFAULT 0,
    HonorariosBase       DECIMAL(18,2) NOT NULL DEFAULT 0,
    HonorariosImporte    DECIMAL(18,2) NOT NULL DEFAULT 0,

    IVAPorc              DECIMAL(5,2)  NOT NULL DEFAULT 0,
    IVABase              DECIMAL(18,2) NOT NULL DEFAULT 0,
    IVAImporte           DECIMAL(18,2) NOT NULL DEFAULT 0,

    -- Columnas heredadas sin uso hoy (el modelo actual no las expone en la UI;
    -- se dejan porque ya existen filas viejas con estas columnas en 0).
    TituloPropiedad       DECIMAL(18,2) NOT NULL DEFAULT 0,
    VEP                   DECIMAL(18,2) NOT NULL DEFAULT 0,
    LibreDeudaInmueble    DECIMAL(18,2) NOT NULL DEFAULT 0,
    LibreDeudaJudicial    DECIMAL(18,2) NOT NULL DEFAULT 0,
    LibreDeudaAgua        DECIMAL(18,2) NOT NULL DEFAULT 0,
    COTI                  DECIMAL(18,2) NOT NULL DEFAULT 0,
    SentenciaDivorcio     DECIMAL(18,2) NOT NULL DEFAULT 0,
    Conformidad           DECIMAL(18,2) NOT NULL DEFAULT 0,
    SaldoDGR              DECIMAL(18,2) NOT NULL DEFAULT 0,
    DecretoAdjudicaciones DECIMAL(18,2) NOT NULL DEFAULT 0,

    -- Otra gestión (trámite personalizado, no predefinido)
    OtraGestionNombre    NVARCHAR(200) NULL,
    OtraGestionImporte   DECIMAL(18,2) NOT NULL DEFAULT 0,

    SubtotalImpuestos    DECIMAL(18,2) NOT NULL DEFAULT 0,
    SubtotalCertificados DECIMAL(18,2) NOT NULL DEFAULT 0,
    TotalGeneral         DECIMAL(18,2) NOT NULL DEFAULT 0,

    Estado               NVARCHAR(20)  NOT NULL DEFAULT 'Pendiente',
    MetodoPago           NVARCHAR(50)  NULL,
    Observaciones        NVARCHAR(500) NULL,

    FechaCreacion        DATETIME      NOT NULL DEFAULT GETDATE(),
    FechaActualizacion   DATETIME      NULL,
    UsuarioCreacion      NVARCHAR(100) NULL,
    UsuarioActualizacion NVARCHAR(100) NULL,
    Eliminado            BIT           NOT NULL DEFAULT 0,

    CONSTRAINT FK_Cobros_Cliente FOREIGN KEY (ClienteId) REFERENCES Cliente(Id)
);
GO

-- =====================================================================
-- 9. ESCRITURA
-- =====================================================================
CREATE TABLE Escritura (
    Id                    INT IDENTITY(1,1) PRIMARY KEY,
    ClienteId             INT           NOT NULL,
    TipoEscrituraId       INT           NOT NULL,
    NumeroProtocolo       NVARCHAR(50)  NOT NULL,
    Fecha                 DATETIME      NOT NULL,
    RutaArchivo           NVARCHAR(500) NULL,
    FormatoArchivo        NVARCHAR(10)  NULL,
    Estado                NVARCHAR(50)  NOT NULL DEFAULT 'Borrador',
    TramiteId             INT           NULL,
    CobroId               INT           NULL,
    Observaciones         NVARCHAR(MAX) NULL,
    FechaCreacion         DATETIME      NOT NULL DEFAULT GETDATE(),
    FechaProtocolizacion  DATETIME      NULL,
    UsuarioCreacion       NVARCHAR(100) NULL,
    Eliminado             BIT           NOT NULL DEFAULT 0,

    CONSTRAINT FK_Escritura_Cliente FOREIGN KEY (ClienteId) REFERENCES Cliente(Id),
    CONSTRAINT FK_Escritura_TipoEscritura FOREIGN KEY (TipoEscrituraId) REFERENCES TipoEscritura(Id),
    CONSTRAINT FK_Escritura_Tramite FOREIGN KEY (TramiteId) REFERENCES tramite(Id),
    CONSTRAINT FK_Escritura_Cobros FOREIGN KEY (CobroId) REFERENCES Cobros(Id)
);
GO

-- =====================================================================
-- 10. PAGOS (abonos individuales contra un Cobro)
-- =====================================================================
CREATE TABLE Pagos (
    Id                INT IDENTITY(1,1) PRIMARY KEY,
    CobroId           INT           NOT NULL,
    MontoPagado       DECIMAL(18,2) NOT NULL,
    FechaPago         DATETIME      NOT NULL,
    MetodoPago        NVARCHAR(50)  NOT NULL,
    NumeroComprobante NVARCHAR(100) NULL,
    Observaciones     NVARCHAR(500) NULL,
    UsuarioRegistro   NVARCHAR(100) NOT NULL,
    FechaRegistro     DATETIME      NOT NULL DEFAULT GETDATE(),

    CONSTRAINT FK_Pagos_Cobros FOREIGN KEY (CobroId) REFERENCES Cobros(Id)
);
GO

-- =====================================================================
-- 11. PEDIDOINSUMO
-- =====================================================================
CREATE TABLE PedidoInsumo (
    Id             INT IDENTITY(1,1) PRIMARY KEY,
    FechaPedido    DATETIME      NOT NULL,
    TipoInsumo     NVARCHAR(100) NOT NULL,
    Cantidad       INT           NOT NULL,
    Solicitante    NVARCHAR(200) NOT NULL,
    Observaciones  NVARCHAR(MAX) NULL,
    Estado         NVARCHAR(50)  NOT NULL DEFAULT 'Pendiente',
    EmailDestino   NVARCHAR(200) NULL,
    Firmado        BIT           NOT NULL DEFAULT 0,
    FechaEnvio     DATETIME      NULL,
    FechaRecepcion DATETIME      NULL,
    Eliminado      BIT           NOT NULL DEFAULT 0
);
GO

-- =====================================================================
-- 12. STOCKINSUMO
-- =====================================================================
CREATE TABLE StockInsumo (
    Id                  INT IDENTITY(1,1) PRIMARY KEY,
    TipoInsumo          NVARCHAR(100) NOT NULL,
    CantidadActual      INT           NOT NULL DEFAULT 0,
    StockMinimo         INT           NOT NULL DEFAULT 10,
    UltimaActualizacion DATETIME      NOT NULL DEFAULT GETDATE()
);
GO

-- =====================================================================
-- 13. REGISTROSAUDITORIA
-- =====================================================================
CREATE TABLE RegistrosAuditoria (
    Id          INT IDENTITY(1,1) PRIMARY KEY,
    FechaHora   DATETIME      NOT NULL DEFAULT GETDATE(),
    Usuario     NVARCHAR(100) NOT NULL,
    Accion      NVARCHAR(50)  NOT NULL,
    Modulo      NVARCHAR(100) NOT NULL,
    EntidadId   INT           NULL,
    Descripcion NVARCHAR(500) NULL
);
GO

PRINT 'Estructura de la base de datos creada correctamente.';
GO

